@section('scripts')
    <script>
        function createRadialBarChart(elementId, seriesValue, gradientColor, label) {
            var options = {
                series: [seriesValue],
                chart: {
                    height: 180,
                    type: 'radialBar',
                    toolbar: {show: false}
                },
                plotOptions: {
                    radialBar: {
                        startAngle: -115,
                        endAngle: 115,
                        hollow: {
                            margin: 0,
                            size: '60%',
                            background: 'transparent'
                        },
                        track: {
                            background: 'rgba(0, 0, 0, 0.1)',
                            strokeWidth: '80%'
                        },
                        dataLabels: {
                            show: true,
                            value: {
                                offsetY: 10,
                                color: '#111',
                                fontSize: '24px',
                                show: false
                            }
                        }
                    }
                },
                fill: {
                    type: 'gradient',
                    gradient: {
                        shade: 'dark',
                        type: 'horizontal',
                        shadeIntensity: 0.5,
                        gradientToColors: [gradientColor],
                        inverseColors: true,
                        opacityFrom: 1,
                        opacityTo: 1,
                        stops: [0, 100]
                    }
                },
                colors: [gradientColor],
                stroke: {lineCap: 'round'},
                labels: [label],
            };

            var chart = new ApexCharts(document.querySelector(elementId), options);
            chart.render();
        }

        createRadialBarChart("#chart-circle-1", 65, "#47ff33", "65%");
        createRadialBarChart("#chart-circle-2", 20, "#ff0808", "20%");
        createRadialBarChart("#chart-circle-3", 50, "#1f35bd", "50%");
        createRadialBarChart("#chart-circle-4", 65, "#47ff33", "65%");
        createRadialBarChart("#chart-circle-5", 65, "#47ff33", "65%");
        createRadialBarChart("#chart-circle-6", 65, "#47ff33", "65%");

        function createCircleChart(id, series = [], labels = []) {
            var options = {
                series: series, // Dynamic series values
                chart: {
                    height: 390,
                    width: 390,
                    type: 'radialBar',
                },
                plotOptions: {
                    radialBar: {
                        offsetY: 0,
                        startAngle: 0,
                        endAngle: 270,
                        track: {
                            background: 'rgba(0, 0, 0, 0.1)',
                            strokeWidth: '30%'
                        },
                        hollow: {
                            margin: 5,
                            size: '60%',
                            background: 'transparent',
                            image: undefined,
                        },
                        dataLabels: {
                            name: {
                                show: false,
                            },
                            value: {
                                show: false,
                            }
                        },
                        barLabels: {
                            enabled: true,
                            useSeriesColors: true,
                            offsetX: -8,
                            fontSize: '16px',
                            formatter: function (seriesName, opts) {
                                return seriesName + ":  " + opts.w.globals.series[opts.seriesIndex];
                            },
                        },
                    }
                },
                colors: ['#6FF25A', '#FFB926', '#FF3B30'],
                labels: labels,
                responsive: [{
                    breakpoint: 480,
                    options: {
                        legend: {
                            show: false,
                        }
                    }
                }]
            };

            var circleChart = new ApexCharts(document.querySelector(`#${id}`), options);
            circleChart.render();
        }


        // Call the function for both charts
        createCircleChart('circle-chart-one', [70, 70, 70], ['completed', 'in-progress', 'Delayed']);
        createCircleChart('circle-chart-two', [20, 70, 80], ['completed', 'in-progress', 'Delayed']);
    </script>
@endsection
